EXPLAIN (ANALYZE,BUFFERS,SETTINGS,VERBOSE) SELECT p.source,p.external_id,p.type,p.number,p.year,p.functional_group,p.label,p.summary,p.presented_at,p.status,p.principal_id,COALESCE(parent.external_id,fallback_parent.parent_external_id) parent_external_id,ARRAY(SELECT a.name FROM civica_poc.proposal_authors a WHERE a.source=p.source AND a.proposal_id=p.external_id ORDER BY a.author_key),ARRAY(SELECT t.label FROM civica_poc.proposal_themes t WHERE t.source=p.source AND t.proposal_id=p.external_id ORDER BY t.label) FROM civica_poc.proposals p JOIN civica_poc.active_publications ap ON ap.source=p.source AND ap.batch_id=p.batch_id LEFT JOIN civica_poc.proposals parent ON parent.batch_id=p.batch_id AND parent.source=p.source AND parent.external_id=p.principal_id LEFT JOIN civica_poc.proposal_parent_context fallback_parent ON fallback_parent.child_source=p.source AND fallback_parent.child_external_id=p.external_id WHERE (p.search_label LIKE '%saude%' OR p.search_summary LIKE '%saude%' OR p.search_type LIKE '%saude%' OR p.search_number LIKE '%saude%' OR EXISTS (SELECT 1 FROM civica_poc.proposal_authors a WHERE a.source=p.source AND a.proposal_id=p.external_id AND a.search_name LIKE '%saude%')) ORDER BY p.year DESC NULLS LAST,p.type,p.number,p.source,p.external_id LIMIT 13;
